  // Check if amount to be refunded is valid
  if (amount <= 0 || amount > getVoucherBalance(voucherId)) {
    return false;
  }

  // Update voucher balance
  double newBalance = getVoucherBalance(voucherId) - amount;
  setVoucherBalance(voucherId, newBalance);

