}

std::string receiveMessage(TCPConnection& connection) {
  char buffer[1024];
  int bytesRead = recv(connection.getSocket(), buffer, sizeof(buffer) - 1, 0);
  if (bytesRead == -1) {
    throw std::runtime_error("Failed to receive message");
  }
  buffer[bytesRead] = '\0';
  return std::string(buffer);
}

