  auto it = scheduledUATs.find(projectID);
  if (it == scheduledUATs.end()) {
    return false;
  }

  auto [start, end] = it->second;
  auto now = std::chrono::system_clock::now();

  if (now >= start && now <= end) {
    return true;
  } else {
    return false;
  }
}

